<?php
/** Four data families and a deliberately bounded read-only product handoff. */
defined('ABSPATH') || exit;
final class WCJ_Data_Exchange_Workspace {
 public static function groups(){return require __DIR__.'/data-exchange-groups.php';}
 public static function edition(){return defined('WCJ_PLUGIN_FILE')&&'booster-elite-for-woocommerce.php'===basename(WCJ_PLUGIN_FILE)?'elite':(defined('WCJ_PLUGIN_FILE')&&'booster-plus-for-woocommerce.php'===basename(WCJ_PLUGIN_FILE)?'plus':'free');}
 public static function capability(){return 'yes'===wcj_get_option('wcj_admin_tools_enabled','no')&&'yes'===wcj_get_option('wcj_admin_tools_show_menus_to_admin_only','no')?'manage_options':'manage_woocommerce';}
 public static function allowed($id){$core=WCJ_Job_Store::core();return in_array($id,array('export','products_xml','reports','track_users'),true)&&current_user_can('manage_woocommerce')&&current_user_can(self::capability())&&$core&&isset($core->all_modules[$id])&&(!function_exists('wcj_is_module_allowed_by_allowlist')||wcj_is_module_allowed_by_allowlist($id))&&(!wcj_is_module_enabled('modules_by_user_roles')||wcj_check_modules_by_user_roles($id));}
 public static function raw($key){global $wpdb;$rows=$wpdb->get_results($wpdb->prepare("SELECT option_value FROM {$wpdb->options} WHERE option_name=%s LIMIT 2",$key),ARRAY_A);if($wpdb->last_error||!is_array($rows)||count($rows)>1){throw new RuntimeException('Saved configuration could not be read safely.');}return $rows?(string)$rows[0]['option_value']:null;}
 public static function flag($value,$default='no'){return null===$value?'No saved value; default '.('yes'===$default?'On':'Off'):('yes'===$value?'Saved On':('no'===$value?'Saved Off':'Saved value needs full settings'));}
 private static function count($value,$default){return null===$value?$default:(preg_match('/\A(?:0|[1-9][0-9]{0,7})\z/D',$value)?$value.' saved':'Saved value needs full settings');}
 private static function selection($value,$default){if(null===$value){return $default;}if(''===$value){return 'Saved empty; see the group explanation';}if(strlen($value)>16384){return 'Saved selection needs full settings';}$a=@unserialize($value,array('allowed_classes'=>false,'max_depth'=>3));if(!is_array($a)||serialize($a)!==$value||count($a)>200){return 'Saved selection needs full settings';}foreach($a as $v){if(!is_string($v)){return 'Saved selection needs full settings';}}return count($a)?count($a).' saved selections':'Saved empty selection; see the group explanation';}
 public static function url(){return admin_url('admin.php?page=wcj-data-exchange');}
 private static function link($url,$label){return '<a target="_blank" rel="noopener noreferrer" href="'.esc_url($url).'">'.esc_html($label.' (new tab)').'</a>';}
 public static function native_url($g){return self::allowed($g['module'])?admin_url(wcj_admin_tab_url().'&section='.$g['module'].'&active_tab='.$g['native_tab']):'';}
 public static function entry(){foreach(array('export','products_xml','reports','track_users') as $m){if(self::allowed($m)){echo '<p><a href="'.esc_url(self::url()).'">Report, export and exchange data: a small product handoff and full data guidance</a></p>';return;}}}
 public static function summaries($module){$r=array('Module'=>self::flag(self::raw('wcj_'.$module.'_enabled')));$free='free'===self::edition();
  if('export'===$module){$r['Output']='Existing tools offer CSV and XML; the small handoff uses its own fixed CSV format';$r['Product fields']=self::selection(self::raw('wcj_export_products_fields'),'No saved selection; existing exporter defaults apply');$r['Additional product fields']=$free?'One slot under the Free rule':self::count(self::raw('wcj_export_products_fields_additional_total_number'),'One by default');$r['Native UTF-8 BOM']=self::flag(self::raw('wcj_export_csv_add_utf_8_bom'),'yes');$r['Private records']='Customers and orders are not read by this workspace or the small handoff';}
  if('products_xml'===$module){$r['Feed count']=$free?'One under the Free rule':self::count(self::raw('wcj_products_xml_total_files'),'One by default');$r['Feed 1']=self::flag(self::raw('wcj_products_xml_enabled_1'),'yes');$period=self::raw('wcj_create_products_xml_period_1');$r['Feed 1 period']=$free?'Weekly under the Free rule':(null===$period?'Weekly by default':(in_array($period,array('minutely','hourly','twicedaily','daily','weekly'),true)?array('minutely'=>'Every minute','hourly'=>'Hourly','twicedaily'=>'Twice daily','daily'=>'Daily','weekly'=>'Weekly')[$period]:'Saved period needs full settings'));$path=self::raw('wcj_products_xml_file_path_1');$r['Feed 1 destination']=null===$path?'No saved path; native default products.xml':(''===$path?'Saved empty path; inspect full settings':'A custom path is saved; inspect it in full settings');$r['Generation status']='No file opened or validated; additional feeds remain in full settings';}
  if('reports'===$module){$r['Daily status basis']=self::selection(self::raw('wcj_reports_products_sales_daily_order_statuses'),'No saved selection; any status in the existing report');$r['Daily displayed columns']=self::selection(self::raw('wcj_reports_products_sales_daily_columns'),'No saved selection; all available report columns');$r['Daily taxes']=self::flag(self::raw('wcj_reports_products_sales_daily_include_taxes'));$r['Monthly forecast']=self::flag(self::raw('wcj_reports_orders_monthly_sales_forecast'));$r['Historical rates']='Read in the existing report; missing matches use 1.0, not live FX';}
  if('track_users'===$module){$r['Dashboard widget']=self::flag(self::raw('wcj_track_users_by_country_widget_enabled'),'yes');$r['Displayed scopes']=self::selection(self::raw('wcj_track_users_by_country_widget_scopes'),'No saved selection; last 24 hours and 28 days by default');$r['Top countries']=self::count(self::raw('wcj_track_users_by_country_widget_top_count'),'Ten by default');$r['Order-source capture']=$free?'Locked in Free; old order information is not erased':self::flag(self::raw('wcj_track_users_save_order_http_referer_enabled'));$last=self::raw('wcj_track_users_cron_time_last_run');$r['Aggregate freshness']=null===$last||''===$last?'No saved last-run timestamp':(preg_match('/\A[0-9]{1,10}\z/D',$last)?'Saved last-run '.gmdate('Y-m-d H:i:s',(int)$last).' UTC; not a delivery guarantee':'Saved timestamp needs full settings');$r['Visitor records']='Not loaded here';}
  return $r;
 }
 public static function help($module='',$pick=array()){$ed=self::edition();foreach(self::groups() as $g){if(($module&&$module!==$g['module'])||($pick&&!in_array($g['id'],$pick,true))||!self::allowed($g['module'])){continue;}echo '<article data-exchange-group="'.esc_attr($g['id']).'"><h3>'.esc_html($g['label']).'</h3><p>'.esc_html($g['context']).'</p><p>'.self::link(self::native_url($g),'Full settings').' | '.self::link($g['guide'],'Guide: '.$g['label']).'</p>';
  if(wcj_is_module_enabled($g['module'])){foreach($g['tools']??array() as $tool){echo '<p>'.self::link(admin_url('admin.php?page=wcj-tools&tab=export_'.$tool.'&wcj_tools_nonce='.wp_create_nonce('wcj_tools')),'Existing tool: '.str_replace('_',' ',$tool)).'</p>';}foreach($g['reports']??array() as $report){echo '<p>'.self::link(admin_url('admin.php?page=wc-reports&tab='.$report['tab'].'&report='.$report['report']),$report['label']).'</p>';}}
  echo '<details><summary>Fields and actions covered</summary><ul>';foreach($g['members'][$ed] as $m){echo '<li>'.esc_html($m['label'].($m['locked']?' (locked in Free)':'')).'</li>';}foreach($g['actions']??array() as $action){echo '<li>'.esc_html($action).'</li>';}echo '</ul></details></article>';}}
 private static function tracking_help( $screen ) {
  if(!$screen||!self::allowed('track_users')||!wcj_is_module_enabled('track_users')){return array();}
  if('dashboard'===$screen->id){return 'yes'===wcj_get_option('wcj_track_users_by_country_widget_enabled','yes')?array('tracking-dashboard'):array();}
  $hpos='woocommerce_page_wc-orders'===$screen->id;$action=$_GET['action']??'';
  if(!is_string($action)){return array();}
  $edit='shop_order'===$screen->id||($hpos&&in_array($action,array('edit','new'),true));
  $list='edit-shop_order'===$screen->id||($hpos&&!$edit&&''===$action);
  if($edit&&'yes'===apply_filters('booster_option','no',wcj_get_option('wcj_track_users_save_order_http_referer_enabled','no'))){return array('tracking-orders');}
  if($list&&('yes'===wcj_get_option('wcj_track_users_shop_order_columns_referer','no')||'yes'===wcj_get_option('wcj_track_users_shop_order_columns_referer_type','no'))){return array('tracking-orders');}
  return array();
 }
 public static function screen_help(){if(!current_user_can('manage_woocommerce')||!current_user_can(self::capability())){return;}$p=$_GET['page']??'';$s=$_GET['section']??'';$tab=$_GET['tab']??'';$active=$_GET['active_tab']??'';$report=$_GET['report']??'';foreach(array($p,$s,$tab,$active,$report) as $v){if(!is_string($v)){return;}}$pick=array();foreach(self::groups() as $g){if(!self::allowed($g['module'])){continue;}if('wcj-plugins'===$p&&$s===$g['module']&&(!$active||$active===$g['native_tab'])){$pick[]=$g['id'];}elseif('wcj-tools'===$p&&in_array(substr($tab,7),$g['tools']??array(),true)&&0===strpos($tab,'export_')){$pick[]=$g['id'];}elseif('wc-reports'===$p){foreach($g['reports']??array() as $r){if($report===$r['report']&&($tab===$r['tab']||!$tab)){$pick[]=$g['id'];}}}}
  $screen=function_exists('get_current_screen')?get_current_screen():null;$pick=array_merge($pick,self::tracking_help($screen));if(!$pick){return;}echo '<div class="notice notice-info"><p><a href="'.esc_url(self::url()).'">Report, export and exchange data</a>. Read the scope before generating, downloading or resetting data.</p><details><summary>These controls: effects and guidance</summary>';self::help('',array_unique($pick));echo '</details></div>';
 }
 public static function register(){if(current_user_can('manage_woocommerce')&&current_user_can(self::capability())){add_submenu_page('woocommerce','Report, export and exchange data','Data exchange',self::capability(),'wcj-data-exchange',array(__CLASS__,'render'));}}
 private static function form(){echo '<form class="wcj-handoff-task"><h2>Small product handoff CSV</h2><p>An explicitly selected product list, not the existing whole-store exporter. Export must be enabled in full settings first. This task never enables it.</p><p>Downloads to this browser and device. This task stores no file or receipt on the server and sends nothing to an external service.</p><label for="wcj-handoff-ids">Product IDs (up to 20 entries)</label><textarea id="wcj-handoff-ids" name="ids" rows="3" maxlength="4096" placeholder="For example: 101, 102, 103" aria-describedby="wcj-handoff-scope"></textarea><p id="wcj-handoff-scope">Separate IDs with commas or new lines. Blank separators are ignored. Duplicates and invalid entries count toward 20. No whole-catalog search or automatic variations.</p><fieldset><legend>Fields</legend>';foreach(WCJ_Product_Handoff_Job::FIELDS as $key=>$title){$fixed=in_array($key,array('id','status'),true);echo '<label><input type="checkbox" name="fields" value="'.esc_attr($key).'" checked'.($fixed?' disabled':'').'> '.esc_html($title.($fixed?' (always included)':'')).'</label> ';}echo '</fieldset><p><label><input type="checkbox" name="nonpublic"> Include drafts, pending and private products I can edit</label></p><p>Published products only unless selected above. Every row requires permission to edit it. Product names and SKUs can contain confidential store information; review before sharing.</p><button class="button button-primary" type="submit">Preview rows</button> <button class="button wcj-handoff-download" type="button" disabled>Download CSV (0 rows)</button><p class="wcj-handoff-status" role="status" aria-live="polite">No preview has run. Nothing has been downloaded by this form.</p><div class="wcj-handoff-output" tabindex="-1"></div><details><summary>Format, product scope and download limits</summary><p>UTF-8 with BOM, comma separators, every cell quoted, quotes doubled, CRLF row endings. Text line endings inside cells are normalized to LF; other unsupported control bytes or invalid text are refused. The preview shows the exact protected cell values.</p><p>Cells that could run as spreadsheet formulas start with an apostrophe, including whitespace-prefixed formulas. This reduces risk but does not remove it. Check how your spreadsheet handles the file before sharing it.</p><p>Only standard simple, variable parent, grouped and external product classes are supported. No variations, trash, custom classes or unsupported statuses. If this task says a product needs an update, review it in the product editor before trying the handoff again. The task does not update the product for you. Name and SKU use WooCommerce stored/edit-context values, not customer-facing formatted values.</p><p>A preview lasts ten minutes in this signed-in session. Download checks permissions and rebuilds the same rows; changed rows or exclusions require another preview. No saved settings, product updates, feed generation or schedules. A download cannot be recalled or undone after saving or sharing.</p></details><p>'.self::link('https://booster.io/docs/woocommerce-export-tools/#booster-v10-s25-product-handoff','Small product handoff guide').' | '.self::link(admin_url(wcj_admin_tab_url().'&section=export&active_tab=export_export_tab'),'Existing Export settings').'</p></form>';}
 public static function render(){if(!current_user_can('manage_woocommerce')||!current_user_can(self::capability())){wp_die('Ask an administrator for access.');}wp_enqueue_style('wcj-data-exchange',wcj_plugin_url().'/assets/css/admin/wcj-data-exchange-workspace.css',array(),'1.0');wp_enqueue_script('wcj-data-exchange',wcj_plugin_url().'/assets/js/admin/wcj-data-exchange-workspace.js',array(),'1.0',true);wp_localize_script('wcj-data-exchange','wcjDataExchange',array('url'=>admin_url('admin-ajax.php'),'nonces'=>array('preview'=>wp_create_nonce('wcj_product_handoff_preview'),'download'=>wp_create_nonce('wcj_product_handoff_download'))));echo '<div class="wrap wcj-data-exchange"><h1>Report, export and exchange data</h1><p>This workspace does not generate, send or schedule anything merely when opened. Already-enabled native features and other plugins can still run as WordPress loads.</p>';if(self::allowed('export')){self::form();}try{foreach(array('export'=>'Export','products_xml'=>'Products XML Feeds','reports'=>'Reports','track_users'=>'User Tracking') as $module=>$label){if(!self::allowed($module)){continue;}$rows=self::summaries($module);echo '<details class="wcj-exchange-family"><summary><strong>'.esc_html($label).'</strong> '.esc_html($rows['Module']).'</summary><dl>';foreach($rows as $k=>$v){echo '<div><dt>'.esc_html($k).'</dt><dd>'.esc_html($v).'</dd></div>';}echo '</dl>';self::help($module);echo '</details>';}}catch(Throwable $e){echo '<p role="alert">Saved configuration could not be read safely. Use full settings.</p>';}echo '</div>';}
}
new WCJ_Product_Handoff_Job();
add_action('admin_menu',array('WCJ_Data_Exchange_Workspace','register'),99);
add_action('admin_notices',array('WCJ_Data_Exchange_Workspace','screen_help'),44);
